(* [comment removed for export] *)
Definition reg_ev (regs : bvmap 5 word) (rest : nat -> word) : nat -> word :=
  fun n => if Nat.ltb n 32 then getr regs (Z_to_bv 5 (Z.of_nat n)) else rest n.

