#[using="Type"] Lemma shifted_bound : forall (x : Z) c c' lo hi,
  (0 <= x < 2 ^ 64)%Z ->
  (lo <= (x + c') mod 2 ^ 64 <= hi)%Z ->
  (0 <= lo)%Z -> (lo <= hi)%Z -> (hi < 2 ^ 64)%Z -> (0 <= lo + (c - c'))%Z -> (hi + (c - c') < 2 ^ 64)%Z ->
  (lo + (c - c') <= (x + c) mod 2 ^ 64 <= hi + (c - c'))%Z.
Proof.
