#[using="Type"] Lemma end_hi_sound : forall segs E M kn b k n lo1 hi1 h1 e,
  know_ok segs E M kn -> base_range kn b = Some (lo1, hi1) -> xhi kn n = Some h1 ->
  end_hi kn b k n lo1 hi1 h1 = Some e ->
