Definition eagree (b : nat) (E E' : env) : Prop :=
  (forall n, (n < b)%nat -> ev E n = ev E' n) /\ eb E = eb E'.

Definition eupd (E : env) (i : nat) (v : word) : env :=
  Env (fun n => if Nat.eqb n i then v else ev E n) (eb E).

