(* [comment removed for export] *)
Definition zf_kind (mk : saddr -> expr -> kentry) (byteof : option byte -> Prop) : Prop :=
  forall E M a n,
    kentry_ok segs E M (mk a n)
    <-> (flat E a (elenZ E n)
         /\ forall i, (0 <= i < elenZ E n)%Z -> byteof (M (Z_to_bv 64 (estart E a + i)))).

