#[using="Type"] Lemma know_ok_fill_intro : forall E M (a : saddr) (n : nat) (ne : expr) c,
  flat E a (Z.of_nat n) -> elenZ E ne = Z.of_nat n ->
  kentry_ok segs E (wbytes M (adenot E a) (repeat (Z_to_bv 8 c) n)) (KFill a ne c).
